head.script:
scwin.onpageload = function() {

};

scwin.trigger1_onclick = function(e) {
    calendar1.setDisabled(true);
};

scwin.checkVal = function() {
	var log = WebSquare.logger.getLog();
	return log.indexOf('Cannot read properties of null') == -1;
}
scwin.checkVal2 = function() {
	return WebSquare.wUnit.getJq('#calendar1').hasClass('w2calendar_disabled');
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");	
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest()
